INSERT INTO animes (id, title, year, studio, genres, rating, episodes, synopsis, poster_url, cast_members) VALUES
(1, 'Fullmetal Alchemist: Brotherhood', 2009, 'Bones', 'Action,Adventure,Fantasy', 9.1, '64 episodes', 'Dua bersaudara Edward dan Alphonse Elric kehilangan tubuh mereka setelah mencoba menghidupkan kembali ibu mereka dengan alkimia terlarang. Mereka mencari Batu Bijak untuk memulihkan apa yang hilang.', 'https://cdn.myanimelist.net/images/anime/1223/96541.jpg', 'Romi Park, Rie Kugimiya, Shinichiro Miki, Fumiko Orikasa'),
(2, 'Attack on Titan', 2013, 'Wit Studio', 'Action,Drama,Fantasy', 8.5, '25 episodes', 'Setelah raksasa pemakan manusia menghancurkan tembok kota, Eren Yeager bersumpah memusnahkan mereka semua dan bergabung dengan pasukan pengintai demi merebut kembali kebebasan umat manusia.', 'https://cdn.myanimelist.net/images/anime/10/47347.jpg', 'Yuki Kaji, Yui Ishikawa, Marina Inoue, Hiroshi Kamiya'),
(3, 'Death Note', 2006, 'Madhouse', 'Mystery,Psychological,Thriller', 8.6, '37 episodes', 'Siswa jenius Light Yagami menemukan buku catatan yang bisa membunuh siapa pun yang namanya ditulis di dalamnya. Ia mulai membersihkan dunia dari kejahatan, sementara detektif misterius L memburunya.', 'https://cdn.myanimelist.net/images/anime/9/9453.jpg', 'Mamoru Miyano, Kappei Yamaguchi, Shido Nakamura, Aya Hirano'),
(4, 'Cowboy Bebop', 1998, 'Sunrise', 'Action,Sci-Fi,Adventure', 8.7, '26 episodes', 'Pada tahun 2071, sekelompok pemburu hadiah di atas pesawat Bebop menjelajahi tata surya sambil dikejar masa lalu masing-masing, diiringi musik jazz yang ikonik.', 'https://cdn.myanimelist.net/images/anime/4/19644.jpg', 'Koichi Yamadera, Unsho Ishizuka, Megumi Hayashibara, Aoi Tada'),
(5, 'Demon Slayer: Kimetsu no Yaiba', 2019, 'Ufotable', 'Action,Fantasy,Supernatural', 8.4, '26 episodes', 'Tanjiro Kamado menjadi pemburu iblis setelah keluarganya dibantai dan adiknya Nezuko berubah menjadi iblis. Ia berlatih keras untuk menemukan obat bagi adiknya.', 'https://cdn.myanimelist.net/images/anime/1286/99889.jpg', 'Natsuki Hanae, Akari Kito, Hiro Shimono, Yoshitsugu Matsuoka'),
(6, 'Spirited Away', 2001, 'Studio Ghibli', 'Adventure,Fantasy,Family', 8.8, '1 film (125 menit)', 'Chihiro, gadis berusia 10 tahun, tersesat ke dunia roh. Setelah orang tuanya berubah menjadi babi, ia bekerja di pemandian air panas para dewa untuk membebaskan mereka.', 'https://cdn.myanimelist.net/images/anime/6/79597.jpg', 'Rumi Hiiragi, Miyu Irino, Mari Natsuki, Takashi Naito'),
(7, 'Your Name', 2016, 'CoMix Wave Films', 'Romance,Drama,Supernatural', 8.8, '1 film (107 menit)', 'Mitsuha, gadis desa, dan Taki, pelajar Tokyo, tiba-tiba saling bertukar tubuh dalam mimpi. Saat mereka mulai saling mengenal, sebuah tragedi yang mengintai menguji ikatan mereka.', 'https://cdn.myanimelist.net/images/anime/5/87048.jpg', 'Ryunosuke Kamiki, Mone Kamishiraishi, Ryo Narita, Aoi Yuki'),
(8, 'Steins;Gate', 2011, 'White Fox', 'Sci-Fi,Thriller,Drama', 9.1, '24 episodes', 'Mahasiswa eksentrik Rintaro Okabe tanpa sengaja menemukan cara mengirim pesan ke masa lalu. Setiap perubahan kecil memicu konsekuensi besar yang memaksanya menanggung beban garis waktu.', 'https://cdn.myanimelist.net/images/anime/5/73199.jpg', 'Mamoru Miyano, Asami Imai, Kana Hanazawa, Tomokazu Seki'),
(9, 'One Punch Man', 2015, 'Madhouse', 'Action,Comedy,Parody', 8.5, '12 episodes', 'Saitama, pahlawan yang bisa mengalahkan musuh apa pun dengan satu pukulan, justru bosan karena tak ada lawan yang sepadan. Ia mencari tantangan nyata sambil menjalani hidup sehari-hari.', 'https://cdn.myanimelist.net/images/anime/12/76049.jpg', 'Makoto Furukawa, Kaito Ishikawa, Hiroki Yasumoto, Yuki Kaji'),
(10, 'Hunter x Hunter (2011)', 2011, 'Madhouse', 'Action,Adventure,Fantasy', 9.0, '148 episodes', 'Gon Freecss, bocah 12 tahun, menjadi Hunter untuk mencari ayahnya. Dalam perjalanannya ia bersahabat dengan Killua, Kurapika, dan Leorio sambil menghadapi bahaya yang kian besar.', 'https://cdn.myanimelist.net/images/anime/1337/99013.jpg', 'Megumi Han, Mariya Ise, Miyuki Sawashiro, Keiji Fujiwara'),
(11, 'Jujutsu Kaisen', 2020, 'MAPPA', 'Action,Supernatural,Fantasy', 8.6, '24 episodes', 'Yuji Itadori menelan jari terkutuk demi menyelamatkan temannya dan menjadi wadah bagi raja kutukan Sukuna. Ia pun bergabung dengan sekolah jujutsu untuk melawan kutukan jahat.', 'https://cdn.myanimelist.net/images/anime/1171/109222.jpg', 'Junya Enoki, Yuma Uchida, Asami Seto, Yuichi Nakamura'),
(12, 'Frieren: Beyond Journey''s End', 2023, 'Madhouse', 'Adventure,Drama,Fantasy', 9.3, '28 episodes', 'Setelah mengalahkan Raja Iblis, penyihir elf Frieren menyadari betapa singkatnya hidup rekan-rekan manusianya. Ia memulai perjalanan baru untuk memahami arti hubungan dan waktu.', 'https://cdn.myanimelist.net/images/anime/1015/138006.jpg', 'Atsumi Tanezaki, Kana Ichinose, Chiaki Kobayashi, Mallorie Rodak'),
(13, 'Violet Evergarden', 2018, 'Kyoto Animation', 'Drama,Fantasy,Slice of Life', 8.5, '13 episodes', 'Mantan prajurit Violet Evergarden bekerja sebagai penulis surat pengganti sambil mencari arti kata terakhir yang diucapkan komandannya: "aku mencintaimu".', 'https://cdn.myanimelist.net/images/anime/1795/95088.jpg', 'Yui Ishikawa, Daisuke Namikawa, Takehito Koyasu, Minori Chihara'),
(14, 'Code Geass: Lelouch of the Rebellion', 2006, 'Sunrise', 'Action,Sci-Fi,Drama', 8.7, '25 episodes', 'Pangeran buangan Lelouch memperoleh kekuatan Geass yang membuat siapa pun menuruti perintahnya. Ia memimpin pemberontakan terhadap Kekaisaran Britannia demi dunia yang lebih baik bagi adiknya.', 'https://cdn.myanimelist.net/images/anime/5/50331.jpg', 'Jun Fukuyama, Takahiro Sakurai, Ami Koshimizu, Kaori Nazuka'),
(15, 'Vinland Saga', 2019, 'Wit Studio', 'Action,Adventure,Drama', 8.7, '24 episodes', 'Thorfinn, pemuda Viking, bergabung dengan pasukan pembunuh ayahnya demi membalas dendam. Perjalanan penuh perang itu perlahan membuatnya mempertanyakan arti kekuatan dan kedamaian.', 'https://cdn.myanimelist.net/images/anime/1500/103005.jpg', 'Yuto Uemura, Takehito Koyasu, Akio Otsuka, Aoi Yuki'),
(16, 'Mob Psycho 100', 2016, 'Bones', 'Action,Comedy,Supernatural', 8.5, '12 episodes', 'Shigeo "Mob" Kageyama, pelajar SMP dengan kekuatan psikis luar biasa, berusaha hidup normal sambil menekan emosinya agar kekuatan itu tidak meledak tak terkendali.', 'https://cdn.myanimelist.net/images/anime/8/80356.jpg', 'Setsuo Ito, Takahiro Sakurai, Kane Kosugi, Miyu Irino'),
(17, 'Haikyu!!', 2014, 'Production I.G', 'Sports,Comedy,Drama', 8.7, '25 episodes', 'Shoyo Hinata, pemain voli bertubuh pendek yang bermimpi menjadi sang "raksasa kecil", bergabung dengan tim SMA Karasuno dan bersaing bersama rival lamanya, Tobio Kageyama.', 'https://cdn.myanimelist.net/images/anime/7/76014.jpg', 'Ayumu Murase, Kaito Ishikawa, Satoshi Hino, Yuki Kaji'),
(18, 'Neon Genesis Evangelion', 1995, 'Gainax', 'Action,Sci-Fi,Psychological', 8.3, '26 episodes', 'Shinji Ikari dipaksa mengendalikan robot raksasa Eva untuk melawan makhluk misterius bernama Angel, sambil bergulat dengan trauma, kesepian, dan hubungan antarmanusia.', 'https://cdn.myanimelist.net/images/anime/1314/108941.jpg', 'Megumi Ogata, Megumi Hayashibara, Kotono Mitsuishi, Yuriko Yamaguchi'),
(19, 'Made in Abyss', 2017, 'Kinema Citrus', 'Adventure,Fantasy,Mystery', 8.7, '13 episodes', 'Riko, gadis yatim yang bercita-cita menjadi penjelajah, turun ke jurang raksasa penuh misteri bersama robot bocah bernama Reg untuk mencari ibunya yang menghilang.', 'https://cdn.myanimelist.net/images/anime/6/86733.jpg', 'Miyu Tomita, Mariya Ise, Mutsumi Tamura, Shiori Izawa'),
(20, 'Spy x Family', 2022, 'Wit Studio', 'Action,Comedy,Slice of Life', 8.6, '25 episodes', 'Mata-mata Twilight harus membangun keluarga palsu demi misi rahasia, tanpa tahu bahwa putri angkatnya seorang telepat dan istrinya adalah pembunuh bayaran.', 'https://cdn.myanimelist.net/images/anime/1441/122795.jpg', 'Takuya Eguchi, Atsumi Tanezaki, Saori Hayami, Ryuichi Kijima')
